T["Alle Oasis-Nutzer bekommen eine Warnung, wenn ein Gebannter in ihrer Gruppe ist, sie einlaedt oder handeln will - und sehen es im Tooltip."] = "BAN対象者がパーティにいる、招待してきた、取引しようとした場合、Oasisユーザー全員に警告が出ます。ツールチップにも表示されます。"
