T["Alle Zusagen auf die Gruppen verteilen und sofort einladen und sortieren."] = "参加登録者を全員パーティに振り分け、すぐに招待して並べ替えます。"
T["Alle ab dem gewaehlten Rang (Rang 1 = Gildenmeister) sehen diese Zentrale und duerfen Module und Durchsagen fuer die Gilde aendern. Die Grenze legt nur der Gildenmeister fest."] = "選択したランク以上 (ランク1 = ギルドマスター) の全員がこの管理画面を表示でき、ギルドのモジュールとアナウンスを変更できます。この基準はギルドマスターだけが設定できます。"
T["Alle ab dem gewaehlten Rang (Rang 1 = Gildenmeister) sehen diese Zentrale und duerfen Module, Erscheinungsbild und Durchsagen fuer die Gilde aendern. Die Grenze legt nur der Gildenmeister fest."] = "選択したランク以上 (ランク1 = ギルドマスター) の全員がこの管理画面を表示でき、ギルドのモジュール、外観、アナウンスを変更できます。この基準はギルドマスターだけが設定できます。"
T["Alle ab dem gewaehlten Rang sehen diese Zentrale und duerfen Module, Durchsagen und Events fuer die Gilde aendern."] = "選択したランク以上の全員がこの管理画面を表示でき、ギルドのモジュール、アナウンス、イベントを変更できます。"
