T["Alle mit Oasis bekommen einen Hinweis mit Sound. Die neueste Durchsage steht 3 Tage oben auf der Uebersicht."] = "Oasis利用者全員にサウンド付きの通知が届きます。最新のアナウンスは3日間、概要の最上部に表示されます。"
