T["Diagnose und Abgleich"] = "診断と同期"
T["Diamant"] = "ダイヤモンド"
T["Diamant = Verbannen (Hexenmeister)"] = "ダイヤモンド = Banish (ウォーロック)"
T["Diamantrahmen"] = "ダイヤモンドフレーム"
T["Die Bank aktualisiert sich, wenn jemand mit Oasis den Gildentresor oeffnet."] = "Oasis利用者がギルド金庫を開くとバンクが更新されます。"
T["Die Bank besucht. Mal kurz nachzaehlen."] = "バンクを訪れた。ちょっと数えるだけ。"
T["Die Bannliste ist leer."] = "BANリストは空です。"
T["Die Charakterstatistik ist in diesem Client nicht verfuegbar."] = "このクライアントではキャラクター統計を利用できません。"
T["Die Chat-Eingabe war von Oasis beruehrt (z.B. 'Anfluestern'-Knopf), danach wurde /target eingegeben."] = "チャット入力にOasisが触れた後 (例: 「ささやく」ボタン)、/target が入力されました。"
T["Die Chat-Eingabe war von Oasis beruehrt (z.B. 'Anfluestern'-Knopf), danach wurde dort ein /cast-Befehl eingegeben."] = "チャット入力にOasisが触れた後 (例: 「ささやく」ボタン)、そこで /cast コマンドが入力されました。"
T["Die Chat-Eingabe war von Oasis beruehrt, danach wurde /focus eingegeben."] = "チャット入力にOasisが触れた後、/focus が入力されました。"
T["Die Chat-Eingabe war von Oasis beruehrt, danach wurde ein Zauber-Befehl eingegeben."] = "チャット入力にOasisが触れた後、スペルコマンドが入力されました。"
T["Die Dungeonkarten haben keine Koordinaten. Klick hier, dann auf die Stelle der Karte, an der du gerade stehst. An zwei weit entfernten Stellen gemacht, zeigt Oasis dich und deine Gruppe auf der Karte - fuer die ganze Gilde."] = "ダンジョンマップには座標がありません。ここをクリックし、マップ上の現在地をクリックしてください。離れた2か所で行うと、Oasisがあなたとパーティをマップに表示します - ギルド全体に有効。"
T["Die Einladung ist nicht mehr da."] = "その招待はもうありません。"
T["Die Farbe der Legenden"] = "伝説の色"
T["Die Gilde abstimmen lassen - jeder Spieler hat eine Stimme, das Ergebnis ist live"] = "ギルドで投票 – 1人1票、結果はリアルタイム"
T["Die Gilde begruesst (moin, hallo, servus ...)"] = "ギルドに挨拶した (hi、hello、morning ...)"
T["Die Gilde bekommt Bescheid"] = "ギルドに通知されます"
T["Die Gilde sieht dabei, wem du antwortest. Standard: aus"] = "誰に反応したかがギルドに見えます。既定: オフ"
T["Die Gilde sieht dein Feuer %d Minuten auf der Karte."] = "ギルドはあなたの火を%d分間マップで見られます。"
T["Die Gilde sieht dein Feuer 15 Minuten auf der Karte."] = "ギルドはあなたの火を15分間マップで見られます。"
T["Die Gilde sieht deine Einladung. Sobald jemand mitspielt, geht es los."] = "ギルドに招待が表示されます。誰かが参加するとゲーム開始です。"
T["Die Gilde sieht in der Chronik, was du erreicht hast"] = "あなたの達成が年代記でギルドに表示されます"
T["Die Gilde sucht gerade nichts aus diesem Dungeon."] = "ギルドは今このダンジョンのものを探していません。"
T["Die Gilde vergibt noch keine Beute-Punkte - deine Werte erscheinen, sobald die Raidleitung einen Raid startet."] = "ギルドはまだ戦利品ポイントを付与していません - レイドリーダーがレイドを開始すると数値が表示されます。"
T["Die Gildenbank wurde noch nicht gelesen"] = "ギルドバンクは未読み取りです"
T["Die Gildenbank wurde noch nie gelesen. Sobald jemand mit Oasis den Gildentresor oeffnet, steht hier alles - fuer die ganze Gilde."] = "ギルドバンクはまだ読み取られていません。Oasis利用者がギルド金庫を開くと、ここにすべて表示されます – ギルド全体に。"
T["Die Gildenleitung benennt Schlachtzugsleiter und Assistenz unter Krone > Module > Raids & Beute (Namen oder ab Gildenrang). Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "ギルド運営が 王冠 > モジュール > レイド & 戦利品 でレイドリーダーとアシスタントを指名します (名前またはギルドランク以上)。進行中のレイドではレイドリーダーとアシスタントも含まれます。"
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlen auch Raidleiter und Assistenten."] = "ギルド運営が 王冠 > モジュール > レイド & 戦利品 でレイドリーダーを指名します。進行中のレイドではレイドリーダーとアシスタントも含まれます。"
T["Die Gildenleitung benennt Schlachtzugsleiter unter Krone > Module > Raids & Beute. Im laufenden Raid zaehlt auch der Raidleiter."] = "ギルド運営が 王冠 > モジュール > レイド & 戦利品 でレイドリーダーを指名します。進行中のレイドではレイドリーダーも含まれます。"
T["Die Gildenleitung erlaubt Gruppensuchen erst ab einem hoeheren Rang."] = "ギルド運営はパーティ募集をより高いランクからのみ許可しています。"
T["Die Gildenleitung erlaubt Umfragen erst ab einem hoeheren Rang."] = "ギルド運営は投票をより高いランクからのみ許可しています。"
T["Die Gildenleitung hat Soundeffekte fuer dich gesperrt."] = "ギルド運営があなたのサウンド効果をミュートしました。"
T["Die Gildenleitung hat die Mitstreiter-Suche abgeschaltet."] = "ギルド運営が仲間探しを無効にしました。"
T["Die Gildenleitung hat offene Einladungen abgeschaltet - fordere jemanden direkt heraus."] = "ギルド運営がオープン招待を無効にしました - 誰かに直接挑戦してください。"
T["Die Gildenleitung legt unter Krone > Module fest, welche Raenge das duerfen."] = "どのランクに許可するかは、ギルド運営が 王冠 > モジュール で設定します。"
T["Die Gildenleitung sehen nur Raenge bis %d (%s). Dein Rang: %d."] = "ギルド運営を閲覧できるのはランク%d (%s) まで。あなたのランク: %d。"
T["Die Gildensuche von WoW hilft beim Finden - neutral, ohne Werbung."] = "WoWのギルド検索が役立ちます - 中立、広告なし。"
T["Die Grenze legt nur der Gildenmeister fest. Rang 1 = Gildenmeister."] = "上限はギルドマスターのみが設定します。ランク1 = ギルドマスター。"
T["Die Knoepfe schreiben den Befehl in die Chatzeile - erst mit Enter wird er ausgefuehrt."] = "ボタンはコマンドをチャット欄に入力します - Enterを押すと実行されます。"
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster (im Kampf nicht - dort gehoert Esc dem Spiel)."] = "ショートカットはWoWのキー割り当ての AddOns > Oasis にもあります。EscでOasisウィンドウが閉じます (戦闘中は不可 - Escはゲーム側のものです)。"
T["Die Kuerzel stehen auch in WoWs Tastaturbelegung unter AddOns > Oasis. Esc schliesst das Oasis-Fenster, solange du zuletzt hineingeklickt hast."] = "ショートカットはWoWのキー割り当ての AddOns > Oasis にもあります。最後にOasisウィンドウ内をクリックしていれば、Escで閉じます。"
T["Die Leiste ist ab dem Einloggen da und bleibt - das X am Fenster schliesst nur das Fenster."] = "バーはログイン時から常に表示されます - ウィンドウのXはウィンドウだけを閉じます。"
T["Die Leiste rollt nach oben weg; Maus an den oberen Rand und sie kommt herunter (nur wenn sie oben angedockt ist)"] = "バーは上に巻き上がって隠れます。マウスを上端に寄せると降りてきます (上部にドッキング時のみ)"
T["Die Leute im Brachland reden ab und zu ueber dich"] = "Barrensの人々が時々あなたの噂をします"
T["Die Oasis gratuliert."] = "Oasisからお祝い申し上げます。"
T["Die Prozentzahl vergleicht die Item-Wertung fuer deine Rolle, nicht deinen gesamten Schaden. Auswirkungen sind Schaetzwerte."] = "パーセントはあなたのロールでのアイテムスコアの比較で、総ダメージではありません。効果は推定値です。"
T["Die Reservierungs-Zeile erscheint nur, wenn du in einer Gruppe oder einem Schlachtzug bist"] = "予約行はパーティまたはレイドにいる間だけ表示されます"
T["Die Schnellen und die Toten"] = "クイック&デッド"
T["Die Statistik liefert derzeit keinen lesbaren Wert."] = "この統計は現在読み取れる値を返しません。"
T["Die Waechter der Sande"] = "The Scale of the Sands"
T["Die Weltkarte geoeffnet. Wo war nochmal Norden?"] = "ワールドマップを開いた。北はどっちだっけ?"
T["Die Wuerfe sind echte /roll-Ergebnisse vom Server. Seid ihr zu weit auseinander, gleicht Oasis sie per Addon-Nachricht ab."] = "ロールはサーバーの本物の /roll 結果です。離れすぎている場合、Oasisがアドオンメッセージで同期します。"
T["Die Zentrale eurer Gilde. In 30 Sekunden kennst du dich aus - hier ist das Wichtigste."] = "ギルドの拠点。30秒で使い方が分かります - 大事な点はこちら。"
T["Die echte Leiste oben zeigt jede Aenderung sofort"] = "上の実際のバーに変更がすぐ反映されます"
T["Die ersten 20 Ausdauer geben je 1, jeder weitere Punkt 10 Gesundheit."] = "最初の20 Staminaは1ポイントにつきHP 1、以降は1ポイントにつきHP 10。"
T["Die ersten animierten Gilden-Emojis"] = "初のアニメーションギルド絵文字"
T["Die ganze Weltkarte mit einem Charakter erkunden"] = "1キャラクターでワールドマップ全体を探索"
T["Die geschuetzte Funktion wurde blockiert. Der genaue Ausloeser ist noch unbekannt."] = "保護された関数がブロックされました。正確な原因はまだ不明です。"
T["Die meiste Beute der Gilde in den letzten 30 Tagen. Glaenzt es? Meins!"] = "過去30日間でギルド最多の戦利品。光ってる? 私の!"
T["Die meiste Zeit mit Gildenmitgliedern in Gruppen"] = "ギルドメンバーとパーティを組んだ時間が最長"
T["Die meisten Geisterlaeufe der Gilde. Der Friedhof hat eine Bank mit deinem Namen."] = "ギルド最多のゴーストラン。墓地にあなたの名前入りベンチがあります。"
T["Die meisten Nachrichten im Gildenchat"] = "ギルドチャットの発言数最多"
T["Die meisten Naechte online"] = "オンラインだった夜が最多"
T["Die meisten Screenshots der Gilde"] = "ギルド最多のスクリーンショット"
T["Die meisten Spruenge der Gilde"] = "ギルド最多のジャンプ"
T["Die meisten Tode der Gilde in den letzten 30 Tagen"] = "過去30日間でギルド最多の死亡"
T["Die meisten Tode der letzten 7 Tage"] = "過去7日間で最多の死亡"
T["Die meisten Todeswuerfeln-Siege der Gilde"] = "ギルド最多のDeathroll勝利"
T["Die meisten Todeswuerfeln-Siege im letzten Monat (Saison)"] = "先月のDeathroll勝利数最多 (シーズン)"
T["Die meisten Umarmungen und Jubel fuer andere"] = "他者へのハグと歓声が最多"
T["Die meisten Wiederbelebungen"] = "最多の蘇生"
T["Die meisten besuchten Gebiete"] = "訪れたゾーンが最多"
T["Die meisten epischen Gegenstaende der Gilde"] = "ギルド最多のエピックアイテム"
T["Die meisten erledigten Auftraege der Gilde"] = "ギルド最多の完了依頼"
T["Die meisten gefangenen Fische"] = "釣った魚が最多"
T["Die meisten vollen Taschen der Gilde"] = "ギルド最多の満杯バッグ"
T["Die neueste Durchsage steht 3 Tage oben auf der Uebersicht."] = "最新のアナウンスは3日間、概要の最上部に表示されます。"
T["Die passende Charakterstatistik wurde noch nicht gefunden."] = "該当するキャラクター統計がまだ見つかっていません。"
T["Die seltensten Gilden-Emojis"] = "最もレアなギルド絵文字"
T["Die vergessenen Teiche"] = "The Forgotten Pools"
T["Die vollstaendigen Lizenztexte liegen im Oasis-Ordner: CREDITS.txt, LICENSE und LICENSE-MIT.txt."] = "ライセンス全文はOasisフォルダにあります: CREDITS.txt、LICENSE、LICENSE-MIT.txt。"
T["Dienstag"] = "火曜日"
T["Diese Abzeichen zeigt deine Profilkarte zuerst - bei dir und bei der Gilde."] = "これらのバッジがプロフィールカードで最初に表示されます - 自分にもギルドにも。"
T["Diese Gildenraenge (0 = Gildenmeister) duerfen im Beuterat abstimmen."] = "これらのギルドランク (0 = ギルドマスター) がルート評議会で投票できます。"
T["Diese Hinweise ausschalten"] = "この通知をオフにする"
T["Diese Quest hat %s, nicht du."] = "このクエストを持っているのは %s で、あなたではありません。"
T["Diese Quest ist nicht in deinem Questlog."] = "このクエストはクエストログにありません。"
T["Diese Regel gibt es schon."] = "このルールは既に存在します。"
T["Diese Seiten stehen als kleine Knoepfe in der eingeklappten Oasis-Leiste - ein Klick oeffnet sie direkt."] = "これらのページは折りたたんだOasisバーに小さなボタンとして並びます - ワンクリックで開けます。"
T["Diese Sitzung: %d EP in %s"] = "今回のセッション: %d XP (%s)"
T["Diese Sprache gilt nach dem naechsten /reload - hier klicken zum Neuladen."] = "この言語は次の /reload 後に適用されます - ここをクリックでリロード。"
T["Diese Taktik ist noch leer."] = "この戦術はまだ空です。"
T["Diese Woche"] = "今週"
T["Diese Woche hat noch niemand eingezahlt."] = "今週はまだ誰も預け入れていません。"
T["Diese Woche ist noch alles offen - wer macht den Anfang?"] = "今週はまだ白紙です - 誰が最初?"
T["Diese Woche noch ruhig."] = "今週はまだ静かです。"
T["Diese Woche:"] = "今週:"
T["Diesen Monat noch keine Spiele."] = "今月はまだ対戦がありません。"
T["Dieser Charakter liegt auf einem anderen WoW-Account und hat dich als Main eingetragen. Nur wenn du bestaetigst, zaehlt er in der Gilde als dein Twink."] = "このキャラクターは別のWoWアカウントにあり、あなたをメインキャラとして登録しました。あなたが承認した場合のみ、ギルド内であなたのサブキャラとして扱われます。"
T["Dieser Client hat keine Sammlungs-Schnittstelle. /oa probe sammlung zeigt Details."] = "このクライアントにはコレクションAPIがありません。/oa probe sammlung で詳細を表示。"
T["Dieser Client liefert keine Addon-Messwerte (C_AddOnProfiler fehlt)."] = "このクライアントはアドオン計測値を提供しません (C_AddOnProfilerなし)。"
T["Dieser Client liefert keine Rufdaten - du siehst nur die Staende der anderen."] = "このクライアントは評判データを提供しません - 他の人の状況のみ表示されます。"
T["Dieser Client meldet keine seltenen Gegner (Schnittstelle fehlt). /oa probe rares zeigt Details."] = "このクライアントはレア敵を報告しません (APIなし)。/oa probe rares で詳細を表示。"
T["Dieser Termin steht im WoW-Kalender. Anmelden kannst du dich dort."] = "このイベントはWoWカレンダーにあります。参加登録はそちらで。"
T["Diplomat"] = "外交官"
T["Dir fehlt nichts, was die Gilde hat - stark!"] = "ギルドが持つものはすべて持っています - お見事!"
T["Dir selbst etwas zugefluestert. Wer sonst hoert dir so gut zu?"] = "自分にささやいた。こんなに聞いてくれる人は他にいない。"
T["Direkt herausfordern"] = "直接挑戦"
T["Discord Voice"] = "Discord Voice"
