T["Discord-Bruecke: Ist sie an, speichert WoW den ganzen Chat (auch Fluestern) im Klartext in Logs/WoWChatLog.txt."] = "Discordブリッジ: オンの場合、WoWはチャット全体 (ささやきを含む) を平文で Logs/WoWChatLog.txt に保存します。"
T["Discord-Link"] = "Discordリンク"
