T["Discord-Link - z.B. discord.gg/deinegilde (Enter speichert)"] = "Discordリンク - 例: discord.gg/yourguild (Enterで保存)"
T["Discord-Nachrichten im Gildenchat zeigen (ueber OasisSync, nach /reload)"] = "Discordのメッセージをギルドチャットに表示 (OasisSync経由、/reload後)"
T["Discord-Nachrichten uebernommen: %d (neue erscheinen erst nach /reload)"] = "取り込んだDiscordメッセージ: %d (新着は /reload 後に表示)"
