T["Doppelte Oasis-XP ab %s fuer %d Stunden!"] = "%sから%d時間、Oasis XPが2倍!"
T["Doppelte Oasis-XP fuer %d Stunden - viel Spass!"] = "%d時間Oasis XPが2倍 - 楽しんで!"
T["Doppelte Oasis-XP fuer alle in der Gilde, 48 Stunden lang. Alle bekommen eine Durchsage."] = "ギルド全員のOasis XPが48時間2倍。全員にアナウンスが届きます。"
T["Doppelte Oasis-XP fuer alle in der Gilde. Alle mit Oasis bekommen eine Durchsage."] = "ギルド全員のOasis XPが2倍 - いつでも開始可能。Oasis利用者全員にアナウンスが届きます。"
T["Doppelter Rechtsklick wirft aus, Fang-Statistik in der Uebersicht"] = "右ダブルクリックでキャスト、釣果統計は概要に"
T["Doppelter Rechtsklick wirft die Angel aus (Angel muss angelegt sein)."] = "右ダブルクリックで釣り糸を投げます (釣り竿の装備が必要)。"
T["Double XP"] = "Double XP"
