T["Nichts angeheftet - Rechtsklick auf ein Gespraech: Anheften."] = "ピン留めなし - 会話を右クリック: ピン留め。"
T["Nichts davon liegt in der Gildenbank."] = "どれもギルドバンクにありません。"
T["Nichts erkannt - ist das der CSV-Export von softres.it?"] = "認識できません - softres.it の CSV エクスポートですか?"
T["Nichts gefunden"] = "見つかりません"
T["Nichts gefunden - Filter lockern oder aufheben."] = "見つかりません - フィルターを緩めるか解除してください。"
T["Nichts gefunden - andere Filter probieren?"] = "見つかりません - 別のフィルターを試しますか?"
T["Nichts gefunden - andere Suche probieren."] = "見つかりません - 別の検索を試してください。"
T["Nichts gefunden - andere Suche probieren?"] = "見つかりません - 別の検索を試しますか?"
T["Nichts gefunden."] = "見つかりません。"
T["Nichts geplant - wie waer's mit einem Termin?"] = "予定なし - イベントを作りませんか?"
T["Nichts gesucht. Trag oben ein, was du brauchst -\nalle mit Oasis sehen es im Tooltip und bekommen beim Looten einen Hinweis."] = "募集中のものはありません。必要なものを上に追加してください -\nOasis 利用者全員のツールチップに表示され、拾ったときに通知されます。"
T["Nichts in Reichweite - oder alles geschafft."] = "範囲内に何もありません - またはすべて完了しています。"
T["Nichts in deinem Levelbereich - schalte auf Alle oder tippe ein Ziel ein."] = "あなたのレベル帯には何もありません - 「すべて」に切り替えるか、目的地を入力してください。"
T["Nichts in der Bank steht gerade auf einer Gesucht-Liste."] = "現在、バンク内に募集リストのアイテムはありません。"
T["Nichts in dieser Kategorie"] = "このカテゴリには何もありません"
T["Nichts passt zu diesen Filtern."] = "このフィルターに一致するものはありません。"
T["Nichts passt zum Filter"] = "フィルターに一致なし"
T["Nichts verworfen."] = "破棄なし。"
T["Nichts zu pruefen."] = "確認するものはありません。"
T["Nie"] = "なし"
T["Niederl."] = "敗"
T["Niederlage"] = "敗北"
T["Niedrigster Beruf +1 - oder 2-4 Elementaressenzen, wenn alle maximal."] = "最も低い専門技術 +1 - すべて最大なら Elemental Essence 2-4 個。"
T["Niemand aus dem Vorschlag ist online."] = "候補の誰もオンラインではありません。"
T["Niemand frei: alle passenden Charaktere sind gebunden, zu niedrig oder nicht freigeschaltet."] = "空きなし: 条件に合うキャラは全員ロックアウト中、レベル不足、またはアチューン未完了です。"
T["Niemand gestorben - sauber gespielt."] = "死者なし - 完璧なプレイです。"
T["Niemand gestorben."] = "死者なし。"
T["Niemand in der Gilde hat diesen Beruf eingetragen."] = "ギルド内にこの専門技術を登録している人はいません。"
T["Niemand in der Gilde hat es gerade - ab auf die Liste!"] = "今はギルドの誰も持っていません - リストに追加しましょう!"
T["Niemand in der Gilde hat etwas mit diesem Namen."] = "その名前のものを持っている人はギルドにいません。"
T["Niemand in der Gruppe kann ihn geben"] = "パーティ内に付与できる人がいません"
T["Niemand in diesem Filter - sehr gut!"] = "このフィルターに該当者なし - 素晴らしい!"
T["Niemand ist fuer Soundeffekte gesperrt."] = "効果音をミュートされている人はいません。"
T["Niemand ist so lange offline."] = "そこまで長くオフラインの人はいません。"
T["Niemand online"] = "オンラインなし"
T["Niemand sonst in der Gilde"] = "ギルド内に他にいません"
T["Niemand steht kurz vor Respektvoll oder Ehrfuerchtig (ab 75 %)."] = "Revered または Exalted 目前の人はいません (75 % 以上)。"
T["Niemand. Stummschalten geht per Rechtsklick auf einen Namen im Gildenchat."] = "なし。ギルドチャットで名前を右クリックするとミュートできます。"
T["Nimm Quests an - Oasis zeigt dir, wer aus der Gilde dieselben hat."] = "クエストを受けましょう - 同じクエストを持つギルドメンバーを Oasis が表示します。"
T["Ninja-Markierung entfernen"] = "ニンジャマークを解除"
T["Noch Standard-Einstellungen."] = "まだ初期設定のままです。"
T["Noch aus"] = "まだオフ"
T["Noch eine Runde - ich will meine Ehre zurueck!"] = "もう一回 - 名誉を取り戻したい!"
T["Noch gesperrt"] = "まだロック中"
T["Noch hat niemand Material beigetragen."] = "まだ誰も素材を提供していません。"
T["Noch kein Crit erfasst. Kritische Treffer zaehlen automatisch, sobald du allein in der offenen Welt kaempfst."] = "クリティカルの記録はまだありません。オープンワールドで単独で戦うと、クリティカルヒットが自動的に記録されます。"
T["Noch kein Highlight - die Woche ist jung."] = "ハイライトはまだありません - 今週は始まったばかりです。"
T["Noch kein Kampf ausgewertet"] = "戦闘の記録はまだありません"
T["Noch kein Muster - dafuer braucht es mehrere Versuche."] = "パターンはまだありません - 複数回の挑戦が必要です。"
T["Noch kein Protokoll."] = "ログはまだありません。"
T["Noch kein Protokoll. Es wird gelesen, wenn jemand mit Oasis die Bank oeffnet."] = "ログはまだありません。Oasis 利用者がバンクを開くと読み込まれます。"
T["Noch kein Ready-Check"] = "レディチェック未実施"
T["Noch kein Ready-Check gelaufen."] = "レディチェックはまだ行われていません。"
T["Noch kein Scan"] = "スキャン未実施"
T["Noch kein Scan - sobald jemand mit Midas scannt, stehen hier Schnaeppchen."] = "スキャン未実施 - 誰かが Midas でスキャンすると、ここに掘り出し物が表示されます。"
T["Noch kein Scan in der Gilde."] = "ギルド内でまだスキャンされていません。"
T["Noch kein Termin - melde dein Interesse, dann weiss die Raidleitung, wann es passt."] = "イベントはまだありません - 参加希望を登録すると、レイドリーダーが都合の良い日を把握できます。"
T["Noch kein Termin geplant. Oben links: Was, Tag, Uhrzeit - dann 'Event anlegen'."] = "予定されたイベントはまだありません。左上で内容、日、時刻を入力し、「イベントを作成」を押してください。"
T["Noch kein Tod - weiter so!"] = "まだ死亡なし - その調子!"
T["Noch kein Tod eines seltenen Gegners erfasst."] = "レア敵の討伐記録はまだありません。"
T["Noch kein lesbarer eigener Crit erfasst. Neue kritische Treffer werden automatisch aufgezeichnet."] = "読み取れる自分のクリティカルはまだ記録されていません。新しいクリティカルヒットは自動的に記録されます。"
T["Noch kein positiver Einzelrekord gemeldet."] = "単発の記録はまだ報告されていません。"
T["Noch keine Abklingzeiten geteilt - wer Transmutation, Mondstoff oder einen Salzstreuer hat, erscheint hier."] = "共有されたクールダウンはまだありません - Transmute、Mooncloth、Salt Shaker を持つ人がここに表示されます。"
T["Noch keine Abzeichen"] = "バッジなし"
T["Noch keine Abzeichen."] = "バッジはまだありません。"
T["Noch keine Antworten."] = "回答はまだありません。"
T["Noch keine Ausruestung bekannt - Spieler in der Naehe anvisieren und betrachten (Oasis betrachtet Mitspieler in der Gruppe automatisch)."] = "装備情報はまだありません - 近くのプレイヤーをターゲットして調べてください (パーティメンバーは Oasis が自動で調べます)。"
T["Noch keine Berufe gelernt."] = "専門技術をまだ習得していません。"
T["Noch keine Beute aus diesem Dungeon im Gilden-Log."] = "このダンジョンの戦利品はまだギルドログにありません。"
T["Noch keine Beute erfasst"] = "戦利品の記録なし"
T["Noch keine Beute erfasst (ab Qualitaet 'Selten', einstellbar)."] = "戦利品の記録はまだありません (レア以上、変更可)。"
T["Noch keine Bewerber. Name oben eintragen - Klick auf den Status schaltet weiter."] = "応募者はまだいません。上に名前を入力してください - ステータスをクリックすると次へ進みます。"
T["Noch keine Bio."] = "自己紹介はまだありません。"
T["Noch keine Daten - Ausruestung kommt mit dem naechsten Abgleich der Oasis-Nutzer."] = "データなし - 装備は次回の Oasis 同期で届きます。"
T["Noch keine Daten - Mitglieder schicken ihre Messung alle 15 Min (ab dieser Version)."] = "データなし - メンバーは 15 分ごとに計測値を送信します (このバージョン以降)。"
T["Noch keine Daten - oeffne einmal das Sammlungsfenster oder trage Reittiere und Haustiere in der Tasche. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "データなし - コレクションウィンドウを一度開くか、マウントやペットをバッグに入れてください。Oasis を使うギルドメンバーはオンラインになるとここに表示されます。"
T["Noch keine Daten aus der Gilde."] = "ギルドのデータはまだありません。"
T["Noch keine Daten von der Gilde."] = "ギルドからのデータはまだありません。"
T["Noch keine Daten. Sobald Gildenmitglieder mit Oasis einloggen, erscheinen ihre Raid-IDs hier."] = "データなし。ギルドメンバーが Oasis でログインすると、ロックアウトがここに表示されます。"
T["Noch keine Dungeon-Laeufe aufgezeichnet."] = "ダンジョン攻略の記録はまだありません。"
T["Noch keine Dungeons geplant."] = "予定されたダンジョンはまだありません。"
T["Noch keine Durchsagen."] = "お知らせはまだありません。"
T["Noch keine Durchsagen. Schreib links die erste - Ueberschrift, Nachricht, senden."] = "お知らせはまだありません。左で最初の 1 件を書きましょう - 見出し、本文、送信。"
T["Noch keine Eintraege."] = "項目はまだありません。"
T["Noch keine Emojis benutzt - Favoriten aus der Emoji-Auswahl erscheinen hier."] = "絵文字はまだ使われていません - 絵文字ピッカーのお気に入りがここに表示されます。"
T["Noch keine Favoriten - Diamant anklicken."] = "お気に入りなし - ダイヤをクリック。"
T["Noch keine Favoriten - Stern oder Rechtsklick auf einen Sound."] = "お気に入りなし - 星をクリックするかサウンドを右クリック。"
T["Noch keine Favoriten.\nRechtsklick auf ein Emoji merkt es hier."] = "お気に入りはまだありません。\n絵文字を右クリックするとここに保存されます。"
T["Noch keine Fluesternachrichten."] = "ささやきはまだありません。"
T["Noch keine Fluesternachrichten. Schreib jemandem aus der Gilde!"] = "ささやきはまだありません。ギルドの誰かに話しかけましょう!"
T["Noch keine Fraktionen entdeckt."] = "発見した勢力はまだありません。"
T["Noch keine Gilden-News."] = "ギルドニュースはまだありません。"
T["Noch keine Gildenziele. Lege das erste an - z. B. eine legendaere Waffe oder Material fuer den Raid."] = "ギルド目標はまだありません。最初の目標を作りましょう - 例: レジェンダリー武器やレイド用素材。"
T["Noch keine Items verlinkt."] = "リンクされたアイテムはまだありません。"
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch - mit Zeitstrahl der Tode und wiederkehrenden Mustern."] = "戦闘レポートはまだありません。最初のボス戦の後、各挑戦がここに表示されます - 死亡タイムラインと繰り返すパターン付き。"
T["Noch keine Kampfberichte. Nach dem ersten Bosskampf steht hier jeder Versuch."] = "戦闘レポートはまだありません。最初のボス戦の後、各挑戦がここに表示されます。"
T["Noch keine Kandidaten. Spiel mit Leuten ausserhalb der Gilde - wer ohne Gilde ist und gut bewertet wird, landet hier."] = "候補者はまだいません。ギルド外の人と遊びましょう - ギルド未所属で評価の高いプレイヤーがここに並びます。"
T["Noch keine Kombos.\nShift+Klick auf mehrere Emojis, dann Merken."] = "コンボはまだありません。\n複数の絵文字を Shift+クリックして「保存」。"
T["Noch keine Kontakte. Geh mit anderen Oasis-Nutzern in eine Gruppe - Oasis merkt sie sich dann hier, auch ohne Gilde."] = "連絡先はまだありません。他の Oasis 利用者とパーティを組むと、ギルドがなくても Oasis がここに記憶します。"
T["Noch keine Meilensteine. Level auf, lern Berufe - hier entsteht deine Geschichte."] = "マイルストーンはまだありません。レベルを上げ、専門技術を学びましょう - あなたの物語はここから始まります。"
T["Noch keine Meldungen aus der Gilde."] = "ギルドからの報告はまだありません。"
T["Noch keine Mitspieler von ausserhalb der Gilde.\nWer mit dir in einer Gruppe war, landet automatisch hier."] = "ギルド外のプレイヤーはまだいません。\nパーティを組んだ相手は自動的にここに表示されます。"
T["Noch keine Momente - spiel einfach, Oasis schreibt mit."] = "思い出はまだありません - 遊ぶだけで Oasis が記録します。"
T["Noch keine Nachrichten im Offizierschat. Alles, was ab jetzt im Kanal /o geschrieben wird, steht hier."] = "オフィサーチャットにメッセージはまだありません。今後 /o に書かれた内容はすべてここに表示されます。"
T["Noch keine Nachrichten. Alles, was ab jetzt im Gildenchat geschrieben wird, landet hier."] = "メッセージはまだありません。今後ギルドチャットに書かれた内容はすべてここに表示されます。"
T["Noch keine Positionen - die Karte fuellt sich, sobald Mitglieder mit Oasis unterwegs sind."] = "位置情報なし - Oasis を使うメンバーが動き出すとマップが埋まります。"
T["Noch keine Positionen."] = "位置情報はまだありません。"
T["Noch keine Posts. Klick auf 'Neuer Schnappschuss' oder auf die Kamera in der Oasis-Leiste!"] = "投稿はまだありません。「新しいスナップショット」か Oasis バーのカメラをクリック!"
T["Noch keine Preise. Sobald jemand mit Midas im AH scannt, stehen sie hier."] = "価格はまだありません。誰かが Midas で AH をスキャンすると、ここに表示されます。"
T["Noch keine Profile gespeichert."] = "保存されたプロフィールはまだありません。"
T["Noch keine Punkte"] = "ポイントなし"
T["Noch keine Punkte.\nSobald ein Offizier einen Raid startet, gibt es Einsatz-Punkte fuer alle, die dabei sind."] = "ポイントはまだありません。\nオフィサーがレイドを開始すると、参加者全員に貢献ポイントが入ります。"
T["Noch keine Raidtage erfasst. Der Raidleiter (mit Oasis) schreibt sie bei jedem Boss-Kill automatisch mit."] = "レイド日の記録はまだありません。レイドリーダー (Oasis 利用) がボス討伐のたびに自動で記録します。"
T["Noch keine Regeln"] = "ルールなし"
T["Noch keine Regeln. Nimm eine Schnell-Vorlage oder leg oben eine eigene an."] = "ルールはまだありません。クイックテンプレートを選ぶか、上で独自のルールを追加してください。"
T["Noch keine Rezepte bekannt.\nOeffne deine Berufsfenster einmal - Oasis teilt sie dann automatisch mit der Gilde."] = "既知のレシピはまだありません。\n専門技術ウィンドウを一度開くと、Oasis がギルドに共有します。"
T["Noch keine Rezepte geteilt.\n\nSobald jemand mit Oasis sein Berufsfenster oeffnet, erscheinen die Rezepte hier. Wer welchen Beruf hat, siehst du schon jetzt:"] = "共有されたレシピはまだありません。\n\nOasis 利用者が専門技術ウィンドウを開くと、レシピがここに表示されます。誰がどの専門技術を持っているかは今でも確認できます:"
T["Noch keine Rufdaten. Sie kommen automatisch, sobald Mitglieder mit Oasis online sind."] = "評判データはまだありません。Oasis を使うメンバーがオンラインになると自動で届きます。"
T["Noch keine Sammlung geteilt. Sobald Gildenmitglieder mit Oasis online sind, erscheinen sie hier."] = "共有されたコレクションはまだありません。Oasis を使うギルドメンバーがオンラインになるとここに表示されます。"
T["Noch keine Sets."] = "セットはまだありません。"
T["Noch keine Sichtung. Sobald jemand mit Oasis einen seltenen Gegner sieht, steht er hier."] = "目撃情報はまだありません。Oasis 利用者がレア敵を見つけると、ここに表示されます。"
T["Noch keine Spiele."] = "ゲームはまだありません。"
T["Noch keine Spielzeiten bekannt. Oasis lernt mit jedem Abend, an dem du online bist - und uebernimmt die Profile der anderen."] = "プレイ時間はまだ不明です。あなたがオンラインの夜ごとに Oasis が学習し、他の人のプロフィールも取り込みます。"
T["Noch keine Suche. Level eingeben und \"Suchen\" klicken - Spieler mit Gilde werden ausgeblendet."] = "検索はまだありません。レベルを入力して「検索」をクリック - ギルド所属のプレイヤーは非表示になります。"
T["Noch keine Taktiken."] = "戦術はまだありません。"
T["Noch keine Taktiken. Die Raidleitung kann je Boss eine kurze Taktik anlegen - alle sehen sie hier und bekommen sie beim Anvisieren angezeigt."] = "戦術はまだありません。レイドリーダーはボスごとに短い戦術を登録できます - 全員がここで確認でき、ボスをターゲットすると表示されます。"
T["Noch keine Talente bekannt. Mitglieder mit Oasis teilen sie automatisch; andere Spieler: anvisieren und betrachten (Rechtsklick > Betrachten) oder hier mit Ziel erneut oeffnen."] = "タレント情報はまだありません。Oasis を使うメンバーは自動で共有します。他のプレイヤーは、ターゲットして調べる (右クリック > 調べる) か、ターゲットした状態でここを開き直してください。"
T["Noch keine Umfragen."] = "投票はまだありません。"
T["Noch keine Vergaben - sie erscheinen hier, sobald die Raidleitung Beute verteilt."] = "配分はまだありません - レイドリーダーが戦利品を配るとここに表示されます。"
T["Noch keine Werte - nach dem naechsten Kampf erscheint hier, wer vorne liegt."] = "数値はまだありません - 次の戦闘後に、誰がリードしているかが表示されます。"
T["Noch keine Wunschtage - tippe an, wann du kannst."] = "希望日なし - 参加できる日を選んでください。"
T["Noch keine Wunschtage gemeldet."] = "希望日はまだ登録されていません。"
T["Noch keine Ziele. Leg oben eins an - Oasis hakt es automatisch ab."] = "目標はまだありません。上で追加すると、Oasis が自動でチェックを付けます。"
T["Noch keine Zusagen - sei der Erste!"] = "参加登録なし - 最初の一人になりましょう!"
T["Noch keine bekannt - sobald jemand mit Oasis eine Quest fuer diesen Dungeon hat, steht sie hier."] = "まだ不明 - Oasis 利用者がこのダンジョンのクエストを持つと、ここに表示されます。"
T["Noch keine eigene Beute"] = "自分の戦利品なし"
