T["Oasis ist bereit"] = "Oasis の準備完了"
T["Oasis kann sehr viel. Waehle, was du nutzen willst - der Rest bleibt erstmal aus und laesst sich jederzeit unter 'Entdecken' einschalten."] = "Oasis は多機能です。使いたいものを選んでください - 残りはひとまずオフのままで、「発見」からいつでもオンにできます。"
T["Oasis laedt noch - gleich nochmal versuchen."] = "Oasis は読み込み中です - 少し待ってからもう一度お試しください。"
