T["Oasis liest nach jedem Kampf Blizzards eingebaute Schadensanzeige - auch in Instanzen."] = "Oasis は戦闘のたびに Blizzard 内蔵のダメージメーターを読み取ります - インスタンス内でも同様です。"
T["Oasis liest nach jedem Kampf Blizzards eingebaute Schadensanzeige - das Kampflog ist in WoW Forever fuer Addons gesperrt. Mitspieler brauchen Oasis ab 0.5.577. Werte, die Blizzard verschluesselt (z.B. in Instanzen), zaehlen nicht."] = "Oasis は戦闘のたびに Blizzard 内蔵のダメージメーターを読み取ります - WoW Forever ではアドオンから戦闘ログを利用できません。他のプレイヤーは Oasis 0.5.577 以降が必要です。Blizzard が秘匿する値 (インスタンス内など) は集計されません。"
T["Oasis oeffnen"] = "Oasis を開く"
T["Oasis oeffnen / schliessen"] = "Oasis を開く / 閉じる"
T["Oasis ohne Gilde"] = "ギルドなしの Oasis"
