T["Wer aus der Gilde das Item auf der Wunschliste hat"] = "このアイテムをウィッシュリストに入れているギルドメンバー"
T["Wer den Bereich in der Navigation sieht (die Gildenleitung sieht immer alles)"] = "ナビゲーションでこのセクションが見える人 (ギルド運営には常にすべて表示)"
T["Wer die Gilde verlassen hat oder entfernt wurde. Kommt jemand zurueck, meldet Oasis das der Gildenleitung."] = "ギルドを脱退または除名された人。戻ってきた場合、Oasisがギルド運営に通知します。"
T["Wer die Krone oben sieht. Ohne Rechte ist sie grau und oeffnet nur eine Vorschau."] = "上部の王冠が見える人。権限がない場合は灰色で、プレビューのみ開きます。"
T["Wer ein Item fuer den Termin reserviert hat, kommt bei Bedarf vor allen anderen."] = "イベントでアイテムを予約した人は、ニードで他の全員より優先されます。"
T["Wer eine Nachricht oben im Gildenchat anpinnen darf"] = "ギルドチャット上部にメッセージを固定できる人"
T["Wer einladen darf, ist noch nicht bekannt - logge einmal mit deinem Main ein, dann merkt sich Oasis die Gildenleitung."] = "招待できる人がまだ不明です - メインキャラで一度ログインすると、Oasisがギルド運営を記憶します。"
T["Wer geht mit nach %s? Ich suche %s"] = "%sに行く人いますか? %sを募集中"
T["Wer hat ...?"] = "誰が持っている ...?"
T["Wer hat das Questitem, das du brauchst? Und wem kannst du helfen?"] = "必要なクエストアイテムを誰が持っている? あなたは誰を手伝える?"
T["Wer hat gerade %s am Lagerfeuer? Ich komme vorbei!"] = "今、焚き火で%sを持っている人いますか? 行きます!"
T["Wer hat was bekommen"] = "誰が何を獲得したか"
T["Wer im Raid Punkte (Einsatz/Beute) buchen darf."] = "レイドでポイント (貢献/戦利品) を記録できる人。"
T["Wer im Raid Punkte (Einsatz/Beute) buchen darf. Wird sofort gespeichert."] = "レイドでポイント (貢献/戦利品) を記録できる人。すぐに保存されます。"
T["Wer in Gruppe oder Raid welche Buffs hat - und was noch fehlt"] = "パーティやレイドで誰がどのバフを持っているか - 足りないものも"
T["Wer in Gruppe oder Raid welche Buffs hat - und wer das Fehlende geben kann"] = "パーティやレイドで誰がどのバフを持っているか - 足りない分を誰がかけられるかも"
T["Wer ist bereit? Ampeln je Spieler"] = "準備OKなのは誰? プレイヤーごとの信号表示"
T["Wer ist da?"] = "誰がいる?"
T["Wer ist diese Woche schon gebunden, wer ist frei und freigeschaltet - Mains und Twinks"] = "今週ロック済みの人、空いていてアチューン済みの人 – メインキャラとサブキャラ"
T["Wer ist in der Gilde, welcher Rang, wer hat altes Oasis."] = "ギルドのメンバー、ランク、古いOasisを使っている人。"
T["Wer ist online"] = "オンラインのメンバー"
T["Wer ist online, wo, mit welchen Berufen - und wer gewinnt das Level-Rennen"] = "誰がオンラインか、どこにいるか、専門技術は何か – レベルレースの勝者は誰か"
T["Wer ist online?"] = "誰がオンライン?"
T["Wer ist wann online"] = "誰がいつオンラインか"
T["Wer ist wie weit"] = "各メンバーの進み具合"
T["Wer kann was herstellen - Rezepte, Material, Preise und Auftraege der Gilde"] = "誰が何を製作できるか – レシピ、素材、価格、ギルドの依頼"
T["Wer kann was herstellen, Markt, Gildenbank"] = "製作できる人、マーケット、ギルドバンク"
T["Wer kann's?"] = "誰が作れる?"
T["Wer koennte mit: %s"] = "参加できそうな人: %s"
T["Wer koennte mit?"] = "参加できそうな人は?"
T["Wer mitkommen will"] = "参加希望者"
T["Wer oft dabei ist und wenig bekommen hat, ist bei 'Bedarf' zuerst dran. Jede Woche verfaellt ein Teil der Punkte."] = "よく参加していて獲得が少ない人が「ニード」で優先されます。ポイントの一部は毎週失効します。"
T["Wer sich mit passender Rolle meldet, wird sofort in deine Gruppe eingeladen."] = "合うロールで応募した人は、すぐにあなたのパーティへ招待されます。"
T["Wer sieht die Gildenleitung?"] = "ギルド運営が見える人は?"
T["Wer steht wo bei welcher Fraktion? Kurz vor dem Ziel, gemeinsam farmen, Fortschritt dieser Woche"] = "誰がどの勢力でどの評判か? 目標間近、一緒にファーム、今週の進捗"
T["Wer stirbt am oeftesten, woran und wo - die Todes-Rangliste der Gilde"] = "誰が一番多く、何で、どこで死ぬか – ギルドの死亡ランキング"
T["Wer teilt am meisten aus, heilt am meisten, steckt am meisten ein?"] = "与ダメージ、回復、被ダメージが最も多いのは誰?"
T["Wer war lange nicht online - aufraeumen mit einem Klick."] = "長期間オフラインの人 - ワンクリックで整理。"
T["Wer zur Gildenleitung gehoert, legt der Gildenmeister unter Krone > Gilde fest."] = "ギルド運営に含める人は、ギルドマスターが王冠 > ギルドで決めます。"
T["Werbung"] = "募集"
T["Werkzeuge"] = "ツール"
T["Werte"] = "ステータス"
T["Werte bringen deiner Rolle nichts"] = "ステータスがロールに合いません"
T["Werte nur zur Info"] = "ステータスは参考のみ"
T["Werte, Jahrbuch, Tagesziel, Rekorde und Abenteuer deines Charakters."] = "キャラクターのステータス、年鑑、デイリー目標、記録、冒険。"
T["Werte: +Heilung, Intelligenz, Willenskraft, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung;Heilen: Verjuengung und Nachwachsen vorab, Heilende Beruehrung fuer grosse Treffer;Tipp: Anregen fuer Mana, Wiedergeburt fuer gefallene Heiler"] = "ステータス: +ヒーリング、知性、精神、MP5;武器: 杖、または片手武器 + ヒーリング付きオフハンド;回復: RejuvenationとRegrowthを先がけ、大きな被弾にはHealing Touch;ヒント: マナにはInnervate、倒れたヒーラーにはRebirth"
T["Werte: +Heilung, Intelligenz, Zauber-Krit (Erleuchtung gibt Mana zurueck), Mana-Reg.;Waffe: Einhandwaffe + Nebenhand/Schild mit Heilung;Heilen: Lichtblitz fuer kleinen Schaden, Heiliges Licht (niedriger Rang) fuer grosse Treffer;Tipp: Segen verteilen, Gottesschutz wenn du gezogen wirst"] = "ステータス: +ヒーリング、知性、スペルクリティカル (Illuminationでマナ還元)、MP5;武器: 片手武器 + ヒーリング付きオフハンド/盾;回復: 小さなダメージにはFlash of Light、大きな被弾にはHoly Light (低ランク);ヒント: Blessingを配り、ヘイトを取ったらDivine Protection"
T["Werte: +Heilung, Mana-Reg. (MP5), Intelligenz - Willenskraft bringt wenig;Waffe: Einhandwaffe + Schild mit Heilung;Heilen: Kettenheilung fuer Gruppen, Welle der Heilung (niedriger Rang) fuer den Tank;Tipp: Manaquelle-Totem stellen, Erdschild auf den Tank"] = "ステータス: +ヒーリング、MP5、知性 - 精神は効果が薄い;武器: 片手武器 + ヒーリング付き盾;回復: パーティにはChain Heal、タンクにはHealing Wave (低ランク);ヒント: Mana Spring Totemを設置、タンクにEarth Shield"
T["Werte: +Heilung, Willenskraft (Meditation: Regeneration auch beim Zaubern), Intelligenz, Mana-Reg.;Waffe: Stab oder Einhandwaffe + Nebenhand mit Heilung, Zauberstab;Heilen: Erneuerung und Machtwort: Schild vorab, Grosse Heilung (niedriger Rang) fuer den Tank;Tipp: Gebet der Heilung fuer die Gruppe, Verblassen bei Aggro"] = "ステータス: +ヒーリング、精神 (Meditation: 詠唱中もマナ回復)、知性、MP5;武器: 杖、または片手武器 + ヒーリング付きオフハンド、ワンド;回復: RenewとPower Word: Shieldを先がけ、タンクにはGreater Heal (低ランク);ヒント: パーティにはPrayer of Healing、ヘイトを取ったらFade"
T["Werte: Ruestung (Baerengestalt vervielfacht sie), Ausdauer, Beweglichkeit (Ausweichen + Ruestung);Waffe: egal fuer den Schaden - nur die Werte zaehlen (Stab/Stangenwaffe mit Ausdauer);Rotation: Zermalmen, Prankenhieb fuer Gruppen, Demoralisierendes Gebruell;Tipp: Staerke fuer mehr Bedrohung, Wutanfall zum Start"] = "ステータス: アーマー (Bear Formで倍増)、スタミナ、敏捷 (回避 + アーマー);武器: ダメージは無関係 - ステータスのみ重要 (スタミナ付きの杖/ポールアーム);ローテーション: Maul、集団にはSwipe、Demoralizing Roar;ヒント: 筋力で脅威値アップ、開幕にEnrage"
T["Werte: Staerke (1 Punkt = 2 AP), Beweglichkeit (AP + Krit), Krit, Treffer bis +9 %;Waffe: egal fuer den Schaden - nur die Werte zaehlen;Rotation: Krallenhieb/Schreddern fuer Combopunkte, dann Wilder Biss;Tipp: Machtwandel (Gestalt neu) fuer Energie, aus dem Schleichen anspringen"] = "ステータス: 筋力 (1ポイント = 2 AP)、敏捷 (AP + クリティカル)、クリティカル、ヒット+9 %まで;武器: ダメージは無関係 - ステータスのみ重要;ローテーション: Claw/Shredでコンボポイント、その後Ferocious Bite;ヒント: パワーシフト (フォームをかけ直す) でエナジー回復、ステルスから開幕"
T["Werte: Staerke (1 Punkt = 2 AP), Krit (loest Schlaghagel aus = schneller schlagen), Treffer bis +9 %;Waffe: langsame Zweihandwaffe - Windzorn trifft pro Schlag, also je langsamer desto mehr Schaden;Rotation: Windzorn-Waffe, Sturmschlag, Erdschock;Tipp: Totem der Staerke der Erde und Windzorn-Totem fuer die Gruppe"] = "ステータス: 筋力 (1ポイント = 2 AP)、クリティカル (Flurry発動 = 攻撃速度アップ)、ヒット+9 %まで;武器: 遅い両手武器 - Windfuryは1振りごとに発動するので、遅いほど高ダメージ;ローテーション: Windfury Weapon、Stormstrike、Earth Shock;ヒント: パーティにStrength of Earth TotemとWindfury Totem"
T["Werte: Staerke (1 Punkt = 2 AP), Krit, Treffer bis +9 %;Waffe: langsamer Zweihaender - Siegel und Richturteil wirken pro Schlag;Rotation: Siegel der Rechtschaffenheit/des Befehls, Richturteil, Siegel neu setzen;Tipp: Weihe nur mit genug Mana, Segen der Macht fuer dich"] = "ステータス: 筋力 (1ポイント = 2 AP)、クリティカル、ヒット+9 %まで;武器: 遅い両手武器 - SealとJudgementは1振りごとに効果;ローテーション: Seal of Righteousness/Command、Judgement、Sealをかけ直す;ヒント: Consecrationはマナに余裕があるときだけ、自分にBlessing of Might"
T["Werte: Treffer bis +9 %, Beweglichkeit (1 AP, ca. 29 = 1 % Krit), AP, Krit;Waffe: Kampf = schnelle Nebenhand, langsame Haupthand (Finsterer Stoss); Dolche fuer Meucheln;Rotation: Combopunkte aufbauen, Zerhaecksler oben halten, dann Ausweiden;Tipp: mit zwei Waffen verfehlen normale Schlaege oefter - Treffer ist am wichtigsten"] = "ステータス: ヒット+9 %まで、敏捷 (1 AP、約29 = 1 %クリティカル)、AP、クリティカル;武器: Combat = 速いオフハンド、遅いメインハンド (Sinister Strike); Backstabにはダガー;ローテーション: コンボポイントを貯め、Slice and Diceを維持、その後Eviscerate;ヒント: 二刀流は通常攻撃が外れやすい - ヒットが最重要"
T["Werte: Treffer bis +9 %, Beweglichkeit (2 Distanz-AP, ca. 53 = 1 % Krit), AP, Intelligenz;Waffe: langsame Distanzwaffe (hoher Schaden pro Schuss), Nahkampfwaffe mit Werten;Rotation: Mal des Jaegers, Automatischer Schuss, Zielschuss/Mehrfachschuss dazwischen;Tipp: Begleiter fuettern und gluecklich halten, Eisfalle (Quadrat) als Kontrolle"] = "ステータス: ヒット+9 %まで、敏捷 (遠隔AP 2、約53 = 1 %クリティカル)、AP、知性;武器: 遅い遠隔武器 (1発のダメージが大きい)、ステータス付き近接武器;ローテーション: Hunter's Mark、Auto Shot、合間にAimed Shot/Multi-Shot;ヒント: ペットにエサを与えて機嫌を保つ、CCにFreezing Trap (四角)"
T["Werte: Treffer bis +9 %, Staerke (1 Punkt = 2 AP), Krit (ca. 20 Beweglichkeit = 1 %);Waffe: langsamer Zweihaender (Toedlicher Stoss, Heldenhafter Stoss wirken pro Schlag);Rotation: Wut aufbauen, Toedlicher Stoss / Blutdurst, Wirbelwind, ueberschuessige Wut in Heldenhaften Stoss;Tipp: Kampfrausch-Ruf vor dem Kampf, Hinrichten unter 20 % Leben"] = "ステータス: ヒット+9 %まで、筋力 (1ポイント = 2 AP)、クリティカル (敏捷約20 = 1 %);武器: 遅い両手武器 (Mortal Strike、Heroic Strikeは1振りごとに効果);ローテーション: レイジを貯め、Mortal Strike / Bloodthirst、Whirlwind、余ったレイジはHeroic Strike;ヒント: 戦闘前にBattle Shout、HP 20 %未満でExecute"
T["Werte: Verteidigung (440 = auf 60 kritsicher gegen Bosse), Ausdauer, Ruestung, Schildblock;Waffe: Einhandwaffe + Schild, schnelle Waffe = mehr Wut;Rotation: Schildschlag/Rachsucht, Ruestung zerreissen auf das Ziel, Heldenhafter Stoss bei viel Wut;Tipp: Treffer hilft, damit Spott und Faehigkeiten nicht verfehlen"] = "ステータス: 防御 (440 = レベル60でボスにクリティカルされない)、スタミナ、アーマー、ブロック;武器: 片手武器 + 盾、速い武器 = レイジ増;ローテーション: Shield Slam/Revenge、ターゲットにSunder Armor、レイジが多いときHeroic Strike;ヒント: ヒットがあるとTauntやアビリティが外れにくい"
T["Werte: Verteidigung, Ausdauer, Ruestung, dann Zauberschaden fuer mehr Bedrohung;Waffe: Einhandwaffe (gern mit Zauberschaden) + Schild;Rotation: Zorn der Gerechtigkeit an, Weihe fuer Gruppen, Heiliger Schild oben halten;Tipp: Mana ist knapp - Siegel der Weisheit oder Intelligenz mitnehmen"] = "ステータス: 防御、スタミナ、アーマー、次に脅威値のためのスペルダメージ;武器: 片手武器 (できればスペルダメージ付き) + 盾;ローテーション: Righteous Furyをオン、集団にはConsecration、Holy Shieldを維持;ヒント: マナが厳しい - Seal of Wisdomか知性を用意"
T["Werte: Zauberschaden, Zauber-Krit (Elementarfokus spart Mana), Intelligenz, Mana-Reg.;Waffe: Einhandwaffe + Schild/Nebenhand mit Zauberschaden;Rotation: Blitzschlag spammen, Kettenblitz bei Gruppen, Flammenschock;Tipp: Zaubertreffer bis +16 % im Raid, Manaquelle-Totem gegen leeres Mana"] = "ステータス: スペルダメージ、スペルクリティカル (Elemental Focusでマナ節約)、知性、MP5;武器: 片手武器 + スペルダメージ付き盾/オフハンド;ローテーション: Lightning Boltを連発、集団にはChain Lightning、Flame Shock;ヒント: レイドではスペルヒット+16 %まで、マナ切れ対策にMana Spring Totem"
T["Werte: Zauberschaden, Zauber-Krit, Intelligenz, Zaubertreffer bis +16 % im Raid;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Mondfeuer + Insektenschwarm, dann Zorn oder Sternenfeuer;Tipp: Anregen fuer dich selbst, wenn das Mana knapp wird"] = "ステータス: スペルダメージ、スペルクリティカル、知性、レイドではスペルヒット+16 %まで;武器: 杖、または片手武器 + スペルダメージ付きオフハンド;ローテーション: Moonfire + Insect Swarm、その後WrathかStarfire;ヒント: マナが減ったら自分にInnervate"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Ausdauer, Intelligenz;Waffe: Stab oder Dolch + Nebenhand mit Zauberschaden, Zauberstab fuer Restmana;Rotation: Verderbnis + Fluch, dann Schattenblitz; Aderlass statt Trinken;Tipp: Ausdauer lohnt sich doppelt (Aderlass, Leerwandler/Seelenverbindung)"] = "ステータス: スペルダメージ、スペルヒット+16 %まで (レイド)、スタミナ、知性;武器: 杖、またはダガー + スペルダメージ付きオフハンド、残りマナ用にワンド;ローテーション: Corruption + カース、その後Shadow Bolt; 飲み物の代わりにLife Tap;ヒント: スタミナは二重に得 (Life Tap、Voidwalker/Soul Link)"
T["Werte: Zauberschaden, Zaubertreffer bis +16 % (Raid), Willenskraft fuer Mana;Waffe: Stab oder Einhandwaffe + Nebenhand mit Zauberschaden;Rotation: Schattenwort: Schmerz, Gedankenschlag, Gedankenschinden;Tipp: Schattengestalt dauerhaft an, Vampirumarmung heilt die Gruppe"] = "ステータス: スペルダメージ、スペルヒット+16 %まで (レイド)、マナ用に精神;武器: 杖、または片手武器 + スペルダメージ付きオフハンド;ローテーション: Shadow Word: Pain、Mind Blast、Mind Flay;ヒント: Shadowformを常時維持、Vampiric Embraceでパーティを回復"
T["Werte: Zauberschaden, dann Zaubertreffer bis +16 % (Raid-Bosse), Intelligenz, Zauber-Krit;Waffe: Stab mit Zauberschaden, dazu ein Zauberstab fuer Restmana;Rotation: Frostblitz bzw. Feuerball spammen, Hervorrufung bei leerem Mana;Leveln: Intelligenz und Willenskraft = weniger Pausen, in Gruppen Schaf (Mond) setzen"] = "ステータス: スペルダメージ、次にスペルヒット+16 %まで (レイドボス)、知性、スペルクリティカル;武器: スペルダメージ付きの杖、残りマナ用にワンド;ローテーション: FrostboltまたはFireballを連発、マナ切れ時にEvocation;レベリング: 知性と精神 = 休憩が減る、パーティではシープ (月) を担当"
