T["Wo ist die Gilde? Punkte auf der Weltkarte und ein Live-Radar fuer dein Gebiet"] = "ギルドはどこ? ワールドマップ上の点と、現在のゾーンのライブレーダー"
T["Wo ist die Gilde? Wer ist in deiner Naehe - mit Entfernung, Richtung und Punkten auf Welt- und Minimap"] = "ギルドはどこ? 近くにいるのは誰か – 距離、方向、ワールドマップとミニマップ上の点で表示"
T["Wo sich die Gilde aufhaelt - aus deiner Position und allen geteilten Gilden-Positionen, jede Minute."] = "ギルドがよくいる場所 - あなたの位置と共有された全ギルド位置から毎分集計。"
T["WoW"] = "WoW"
T["WoW Classic"] = "WoW Classic"
T["WoW Classic hat keine Dungeon-Karten. Das kostenlose Addon Atlas bringt sie mit:"] = "WoW Classicにはダンジョンマップがありません。無料アドオンAtlasで追加できます:"
T["WoW Forever Start"] = "ローンチ"
T["WoW erlaubt das Addons nicht direkt - Enter druecken zum Verlassen."] = "WoWはアドオンによる直接実行を許可していません - Enterを押して退出してください。"
T["WoW erlaubt hoechstens 10 Raenge."] = "WoWで作れるランクは最大10個です。"
T["WoW gibt den Inhalt nur heraus, solange jemand am Gildentresor steht."] = "WoWは誰かがギルドバンクの前にいる間しか中身を提供しません。"
T["WoW hat die Aenderung nicht angenommen (evtl. nur in Ruhe-Zonen oder ausserhalb von Instanzen moeglich)."] = "WoWが変更を受け付けませんでした (休息エリア内かインスタンス外でのみ可能な場合があります)。"
T["WoW sagt Addons in der Gruppe nicht, wer getroffen hat. Oasis zaehlt einen kritischen Treffer nur, wenn er direkt auf deinen eigenen Angriff folgt und nach dem Kampf zur Schadensanzeige passt. In der Rangliste als geschaetzt markiert."] = "パーティ中、WoWは誰の攻撃が当たったかをアドオンに伝えません。Oasisは、自分の攻撃の直後に発生し、戦闘後にダメージメーターと一致するクリティカルヒットだけを数えます。ランキングでは推定値として表示されます。"
T["WoW sperrt einige Funktionen fuer Addons (Kampf, Boss, Chat-Eingabe). Hier steht, welche Funktion es war und was Oasis davor gemacht hat."] = "WoWは一部の機能をアドオンに対して制限しています (戦闘、ボス、チャット入力)。ここには、どの機能だったか、その前にOasisが何をしたかが表示されます。"
