T["Zeigt BESSER / SCHLECHTER / NICHT TRAGBAR mit Auswirkung (DPS, Leben, Ruestung) und Werte-Tabelle. Blizzards Vergleich erscheint dann nur mit Shift. Ist nesUI mit eigenem Vergleich geladen, zeigt Oasis nichts (sonst doppelt) - dort mit /nes vergleich abschalten."] = "「良い / 悪い / 装備不可」を効果 (DPS、HP、アーマー) とステータス表付きで表示します。Blizzardの比較はShiftを押したときだけ表示されます。独自の比較機能を持つnesUIが読み込まれている場合、Oasisは何も表示しません (重複防止) - nesUI側で/nes vergleichを使ってオフにできます。"
T["Zeigt Besser / Schlechter / Nicht tragbar mit Auswirkung (DPS, Leben, Ruestung) und Werte-Tabelle. Blizzards Vergleich erscheint dann nur mit Shift. Ist nesUI mit eigenem Vergleich geladen, zeigt Oasis nichts (sonst doppelt) - dort mit /nes vergleich abschalten."] = "「良い / 悪い / 装備不可」を効果 (DPS、HP、アーマー) とステータス表付きで表示します。Blizzardの比較はShiftを押したときだけ表示されます。独自の比較機能を持つnesUIが読み込まれている場合、Oasisは何も表示しません (重複防止) - nesUI側で/nes vergleichを使ってオフにできます。"
T["Zeigt Beute aus Dungeons deines Levelbereichs, die besser ist als dein angelegtes Teil."] = "レベル帯に合うダンジョンの戦利品のうち、装備中より良いものを表示します。"
T["Zeigt Oasis-Nachrichten im Chat"] = "Oasisのメッセージをチャットに表示"
T["Zeigt ab Oasis-Rang 30 ein Juwel und ab Rang 70 einen schimmernden Namen im Oasis-Gildenchat"] = "Oasisギルドチャットで、Oasisランク30から宝石、ランク70からきらめく名前を表示"
T["Zeigt ab und zu typische Brachland-Sprueche im allgemeinen Chat - Chuck Norris, Mankriks Frau ... Nur bei dir, nichts wird gesendet."] = "一般チャットにBarrensチャットの定番ネタをときどき表示します - Chuck Norris、Mankrik's wife ... あなたにだけ表示され、何も送信されません。"
T["Zeigt ab und zu typische Brachland-Sprueche im allgemeinen Chat - Chuck Norris, Mankriks Frau ... Nur bei dir, nichts wird gesendet. Klick: umschalten"] = "一般チャットにBarrensチャットの定番ネタをときどき表示します - Chuck Norris、Mankrik's wife ... あなたにだけ表示され、何も送信されません。クリック: 切り替え"
T["Zeigt bei gruenen, blauen und epischen Teilen, welche Materialien beim Entzaubern herauskommen koennen"] = "緑・青・エピックのアイテムをディスエンチャントして得られる素材を表示"
T["Zeigt die Levelspanne der Gebiete"] = "各ゾーンのレベル帯を表示"
T["Zeigt dir die Krone und die Gildenleitung wie einem Gildenmeister - nur auf deinem PC. Die Gilde sieht davon nichts."] = "ギルドマスターと同じように王冠とギルド運営を表示します – あなたのPCだけです。ギルドには何も見えません。"
T["Zeigt einen Hinweis, sobald jemand aus der Gilde einen neuen Termin anlegt"] = "ギルドメンバーが新しいイベントを作成すると通知を表示"
T["Zeigt im Brachland ab und zu typische Sprueche im allgemeinen Chat - Chuck Norris, Mankriks Frau ... Nur bei dir, nichts wird gesendet."] = "Barrensにいるとき、一般チャットにBarrensチャットの定番ネタをときどき表示します - Chuck Norris、Mankrik's wife ... あなたにだけ表示され、何も送信されません。"
T["Zeigt im Item-Tooltip, wer das Item fuer einen anstehenden Termin reserviert hat"] = "今後のイベントでそのアイテムを予約した人をアイテムツールチップに表示"
T["Zeigt im Tooltip, wer in der Gilde das Item herstellen kann"] = "そのアイテムを製作できるギルドメンバーをツールチップに表示"
